mapper.delete:
DELETE FROM platform_acl_entry

    principal_id = #{principalId}
    AND resource_type = #{resourceType}
    AND resource_id = #{resourceId}
    AND action = #{action}
    AND FALSE

mapper.select:
SELECT principal_id, resource_type, resource_id, action FROM platform_acl_entry
WHERE principal_id = #{principalId} AND resource_type = #{resourceType}
AND resource_id = #{resourceId}
AND action = #{action}
ORDER BY resource_id, action
LIMIT #{limit}
